/// <summary>
/// Converts a <c>real</c> value to its string representation using the number of decimals present in the value.
/// </summary>
/// <param name="_realValue">The <c>real</c>real value to convert.</param>
/// <returns>
/// A <c>str</c> containing the string representation of the <c>real</c> value.
/// </returns>
public static str real2Str(real _realValue)
{
    return num2Str(_realValue, 1, numOfDec(_realValue), 2, 1);
}

/// <summary>
/// Validates the format of an email address.
/// </summary>
/// <param name = "_eMail">The email address to validate. </param>
/// <returns>True if the email address is valid; otherwise, false. </returns>
public static boolean validateEMail_AVA(EMail _eMail)
{
    Boolean   xppBool;
    System.Boolean netBool;

    System.Text.RegularExpressions.Match myMatch;

    myMatch = System.Text.RegularExpressions.Regex::Match(_eMail, Global::EmailPatternRegEx);
    netBool = myMatch.get_Success();
    xppBool = netBool;

    return xppBool;
}

/// <summary>
/// Validates the format of a URL.
/// </summary>
/// <param name = "_url">The URL to validate.</param>
/// <returns>True if the URL is valid; otherwise, false.</returns>
public static Boolean validateUrl_AVA(URL _url)
{
    Boolean xppBool;
    System.Boolean netBool;

    System.Text.RegularExpressions.Match match;
    match = System.Text.RegularExpressions.Regex::Match(_url,Global::UrlPatternRegEx);
    netBool = match.get_Success();
    xppBool = netBool;

    Return xppBool;

}

/// <summary>
/// Researches all data sources of the specified form.
/// </summary>
/// <param name = "_formRun">The form to research data sources for.</param>
public static void researchAllFormDataSources_AVA(FormRun _formRun)
{
    if (!_formRun)
    {
        return;
    }

    int dataSourceCount = _formRun.dataSourceCount();

    for (int i = 1; i <= dataSourceCount; i++)
    {
        FormDataSource formDS = _formRun.dataSource(i);

        if (formDS)
        {
            formDS.research();
        }
    }
}
